def optimize(versions, bursts, cache_pages, costs):
    """Batch all version trees into one exact shared-residency optimization."""
    hit, miss, dec = costs
    lines = [f'OPTIMIZE {len(versions)} {cache_pages} {hit} {miss} ' +
             ' '.join(map(str, dec))]
    for starts, hops in versions:
        lines.append(str(len(starts)))
        lines.extend(f'{x:032x} {-1 if h is None else h}'
                     for x, h in zip(starts, hops))
    lines.append(str(len(bursts)))
    for version, repeat, addresses in bursts:
        lines.append(f'{version} {repeat} {len(addresses)}')
        lines.extend(f'{x:032x}' for x in addresses)
    output = iter(run(lines))
    objective = list(map(int, next(output).split()))
    images = [next(output) for _ in versions]
    answers = []
    for _, _, addresses in bursts:
        rows = []
        for _ in addresses:
            hop, run_index, count, *path = map(int, next(output).split())
            if count != len(path):
                raise RuntimeError('optimizer path framing')
            rows.append([None if hop == -1 else hop, run_index, path])
        answers.append(rows)
    if next(output, None) is not None:
        raise RuntimeError('optimizer framing')
    return objective, images, answers
